catalog_script_client.script:
function onSubmit() {
	debugger;
	g_form.clearMessages();

	if (!validaDatas()) {
		return false;
	}

	var dupSer = g_form.getValue("serial_dup_check");
	var dupFing = g_form.getValue("fingerprint_dup_check");
	if (dupSer != "OK" || dupFing != "OK") {
		if (dupSer == "pending" || dupFing == "pending") {
			g_form.addErrorMessage(
				"Ainda validando Serial Number e Fingerprint. Aguarde e ressubmeta.",
			);
			return false;
		}
		if (dupSer == "ERROR") {
			g_form.addErrorMessage("Corrija o Serial Number e ressubmeta.");
			return false;
		}
		if (dupFing == "ERROR") {
			g_form.addErrorMessage("Corrija o Fingerprint e ressubmeta.");
			return false;
		}
		if (dupSer != "OK") {
			g_form.addErrorMessage("Serial Number é obrigatório.");
			return false;
		}
	}
	return true;
}

// Valida inicio_de_validade e fim_de_validade
function validaDatas() {
	var inicioStr = g_form.getValue("inicio_de_validade");
	var fimStr = g_form.getValue("fim_de_validade");

	if (!inicioStr || !fimStr) {
		g_form.addErrorMessage("Preencha o início e o fim de validade.");
		return false;
	}

	var inicio = parseUserDate(inicioStr);
	if (!inicio) {
		g_form.addErrorMessage("Início de validade inválido: " + inicioStr);
		return false;
	}
	var fim = parseUserDate(fimStr);
	if (!fim) {
		g_form.addErrorMessage("Fim de validade inválido: " + fimStr);
		return false;
	}

	if (fim <= inicio) {
		g_form.addErrorMessage(
			"O fim de validade deve ser posterior ao início de validade.",
		);
		return false;
	}

	// Certificado já expirado
	//   if (fim < new Date()) {
	//     g_form.addErrorMessage(
	//       "O fim de validade já passou (certificado expirado).",
	//     );
	//     return false;
	//   }

	return true;
}

// Converte o valor do campo (no formato do usuário) em Date; null se inválido
function parseUserDate(value) {
	var formats = [];
	if (typeof g_user_date_time_format != "undefined") {
		formats.push(g_user_date_time_format);
	}
	if (typeof g_user_date_format != "undefined") {
		formats.push(g_user_date_format);
	}
	formats.push("yyyy-MM-dd HH:mm:ss", "yyyy-MM-dd");

	for (var i = 0; i < formats.length; i++) {
		var date = parseWithFormat(value, formats[i]);
		if (date) {
			return date;
		}
	}
	return null;
}

function parseWithFormat(value, format) {
	var order = [];
	var pattern = format
		.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
		.replace(/yyyy|MM|dd|HH|mm|ss/g, function (token) {
			order.push(token);
			return token == "yyyy" ? "(\\d{4})" : "(\\d{1,2})";
		});

	var match = value.trim().match(new RegExp("^" + pattern + "$"));
	if (!match) {
		return null;
	}

	var p = { yyyy: 0, MM: 1, dd: 1, HH: 0, mm: 0, ss: 0 };
	for (var i = 0; i < order.length; i++) {
		p[order[i]] = parseInt(match[i + 1], 10);
	}

	var date = new Date(p.yyyy, p.MM - 1, p.dd, p.HH, p.mm, p.ss);
	// Rejeita datas inexistentes (ex.: 31/02)
	if (
		date.getFullYear() != p.yyyy ||
		date.getMonth() != p.MM - 1 ||
		date.getDate() != p.dd
	) {
		return null;
	}
	return date;
}
